import{_ as t,c as n,o as i,ae as o}from"./chunks/framework.DMK_uHmU.js";const u=JSON.parse('{"title":"Content Manager User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Content/content-managment.md","filePath":"Administration/AI-Management/Content/content-managment.md"}'),a={name:"Administration/AI-Management/Content/content-managment.md"};function l(r,e,s,c,d,h){return i(),n("div",null,e[0]||(e[0]=[o('<h1 id="content-manager-user-guide" tabindex="-1">Content Manager User Guide <a class="header-anchor" href="#content-manager-user-guide" aria-label="Permalink to &quot;Content Manager User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#content-manager-user-guide">Content Manager User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-content-manager">Accessing Content Manager</a></li><li><a href="#content-manager-interface-overview">Content Manager Interface Overview</a></li><li><a href="#viewing-content">Viewing Content</a><ul><li><a href="#content-list-components">Content List Components</a></li><li><a href="#content-type-icons">Content Type Icons</a></li></ul></li><li><a href="#searching-and-filtering-content">Searching and Filtering Content</a><ul><li><a href="#global-search">Global Search</a></li><li><a href="#content-type-filtering">Content Type Filtering</a></li><li><a href="#knowledge-base-filtering">Knowledge Base Filtering</a></li><li><a href="#topic-and-tag-filtering">Topic and Tag Filtering</a></li><li><a href="#quick-filters">Quick Filters</a></li><li><a href="#clearing-filters">Clearing Filters</a></li></ul></li><li><a href="#managing-content">Managing Content</a><ul><li><a href="#adding-new-content">Adding New Content</a></li><li><a href="#viewing-and-editing-content">Viewing and Editing Content</a></li></ul></li><li><a href="#content-operations">Content Operations</a><ul><li><a href="#exporting-content-list">Exporting Content List</a></li><li><a href="#refreshing-content-data">Refreshing Content Data</a></li></ul></li><li><a href="#understanding-content-types">Understanding Content Types</a><ul><li><a href="#documents">Documents</a></li><li><a href="#cards">Cards</a></li><li><a href="#web-links">Web Links</a></li><li><a href="#assets">Assets</a></li><li><a href="#other-content-types">Other Content Types</a></li></ul></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Content Manager provides a comprehensive interface for viewing, creating, and managing all content within your AI Assistant platform. This centralized hub allows you to work with various types of content including documents, cards, links, and assets. The Content Manager makes it easy to find, filter, and organize content across your knowledge bases.</p><h2 id="accessing-content-manager" tabindex="-1">Accessing Content Manager <a class="header-anchor" href="#accessing-content-manager" aria-label="Permalink to &quot;Accessing Content Manager&quot;">​</a></h2><p>The Content Manager is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component, navigate to the Content section in the main navigation menu. The default view shows all content across the system.</p><h2 id="content-manager-interface-overview" tabindex="-1">Content Manager Interface Overview <a class="header-anchor" href="#content-manager-interface-overview" aria-label="Permalink to &quot;Content Manager Interface Overview&quot;">​</a></h2><p>The Content Manager consists of these key components:</p><ol><li><strong>Header Section</strong>: Contains the title &quot;Content Manager&quot; with content count badge, description, and Add button</li><li><strong>Search and Filter Controls</strong>: Tools for finding specific content including global search, content type filters, knowledge base filters, and quick filters</li><li><strong>Data Table</strong>: Displays content items in a sortable, filterable table</li><li><strong>Action Buttons</strong>: Quick access to refresh data, clear filters, and export to Excel</li></ol><h2 id="viewing-content" tabindex="-1">Viewing Content <a class="header-anchor" href="#viewing-content" aria-label="Permalink to &quot;Viewing Content&quot;">​</a></h2><h3 id="content-list-components" tabindex="-1">Content List Components <a class="header-anchor" href="#content-list-components" aria-label="Permalink to &quot;Content List Components&quot;">​</a></h3><p>The content list displays comprehensive information about each content item:</p><ol><li><strong>Content Type Icon</strong>: Visual indicator showing the type of content (document, card, link, etc.)</li><li><strong>Name/Description</strong>: The primary identifier and explanatory text for each content item</li><li><strong>Knowledge Base Associations</strong>: Visual representation of knowledge bases containing this content</li><li><strong>Topic Tags</strong>: Categorization labels for the content</li><li><strong>Content Tags</strong>: Additional classification tags</li><li><strong>Update Information</strong>: When the content was last modified</li></ol><h3 id="content-type-icons" tabindex="-1">Content Type Icons <a class="header-anchor" href="#content-type-icons" aria-label="Permalink to &quot;Content Type Icons&quot;">​</a></h3><p>Different icons represent various content types:</p><ul><li><strong>Documents</strong>: File-specific icons for PDF, Word, Excel, PowerPoint, etc.</li><li><strong>Cards</strong>: Credit card icon</li><li><strong>Links</strong>: Link icon</li><li><strong>FAQ Items</strong>: List icon</li><li><strong>Assets</strong>: Image icon</li><li><strong>Featured Content</strong>: Grid icon</li><li><strong>Web Crawler Content</strong>: Sitemap icon</li></ul><h2 id="searching-and-filtering-content" tabindex="-1">Searching and Filtering Content <a class="header-anchor" href="#searching-and-filtering-content" aria-label="Permalink to &quot;Searching and Filtering Content&quot;">​</a></h2><h3 id="global-search" tabindex="-1">Global Search <a class="header-anchor" href="#global-search" aria-label="Permalink to &quot;Global Search&quot;">​</a></h3><p>The search box at the top of the interface searches across multiple content fields:</p><ul><li>Content name</li><li>Description</li><li>Tags</li><li>Topics</li><li>Content ID</li><li>User names (created/updated by)</li></ul><p>Enter text in the search box to instantly filter the list to matching content items.</p><h3 id="content-type-filtering" tabindex="-1">Content Type Filtering <a class="header-anchor" href="#content-type-filtering" aria-label="Permalink to &quot;Content Type Filtering&quot;">​</a></h3><p>To filter content by type:</p><ol><li><p>Click the &quot;Type&quot; button to open the content type selection menu</p></li><li><p>Options include:</p><ul><li><strong>All Content</strong>: Shows all content types</li><li><strong>PDF</strong>: Only PDF documents</li><li><strong>MS Word</strong>: Word documents (.doc, .docx)</li><li><strong>MS Excel</strong>: Excel spreadsheets (.xls, .xlsx)</li><li><strong>MS PowerPoint</strong>: PowerPoint presentations (.ppt, .pptx)</li><li><strong>Rich Text</strong>: RTF documents</li><li><strong>Text File</strong>: Plain text files (.txt)</li><li><strong>CSV</strong>: Comma Separated Value files</li><li><strong>JSON</strong>: JSON data files</li><li><strong>XML</strong>: XML data files</li><li><strong>HTML</strong>: Web page files</li><li><strong>Video MP4</strong>: Video files</li><li><strong>Audio MP3</strong>: Audio files</li><li><strong>Markdown</strong>: MD files</li><li><strong>Web Link</strong>: External links</li></ul></li><li><p>The selected filter displays on the button (e.g., &quot;PDF&quot; or &quot;Link&quot;)</p></li><li><p>The list updates to show only content of the selected type</p></li></ol><h3 id="knowledge-base-filtering" tabindex="-1">Knowledge Base Filtering <a class="header-anchor" href="#knowledge-base-filtering" aria-label="Permalink to &quot;Knowledge Base Filtering&quot;">​</a></h3><p>To filter content by knowledge base:</p><ol><li>Click the &quot;KB&quot; button to open the knowledge base selection menu</li><li>Options include: <ul><li><strong>All KBs</strong>: Shows content from all knowledge bases</li><li>Individual knowledge bases listed by name</li></ul></li><li>The selected KB name displays on the button</li><li>The list updates to show only content in the selected knowledge base</li></ol><h3 id="topic-and-tag-filtering" tabindex="-1">Topic and Tag Filtering <a class="header-anchor" href="#topic-and-tag-filtering" aria-label="Permalink to &quot;Topic and Tag Filtering&quot;">​</a></h3><p>To filter by topics or tags:</p><ol><li>Click the filter icon in the column header for Topics or Tags</li><li>Select from the dropdown list of available topics or tags</li><li>The list updates to show only content with the selected topic or tag</li></ol><h3 id="quick-filters" tabindex="-1">Quick Filters <a class="header-anchor" href="#quick-filters" aria-label="Permalink to &quot;Quick Filters&quot;">​</a></h3><p>Pre-configured filters for common scenarios:</p><ol><li><strong>My</strong>: Shows only content updated by the current user</li><li><strong>Recent</strong>: Sorts content by update date with newest items first</li></ol><h3 id="clearing-filters" tabindex="-1">Clearing Filters <a class="header-anchor" href="#clearing-filters" aria-label="Permalink to &quot;Clearing Filters&quot;">​</a></h3><p>When filters are active, a &quot;Filter On&quot; indicator appears and the filter button turns blue.</p><p>To clear all active filters:</p><ol><li>Click the filter slash button (filter icon with a slash)</li><li>All filters will be reset to their default state</li><li>The complete content list will be displayed</li></ol><h2 id="managing-content" tabindex="-1">Managing Content <a class="header-anchor" href="#managing-content" aria-label="Permalink to &quot;Managing Content&quot;">​</a></h2><h3 id="adding-new-content" tabindex="-1">Adding New Content <a class="header-anchor" href="#adding-new-content" aria-label="Permalink to &quot;Adding New Content&quot;">​</a></h3><p>To add new content:</p><ol><li><p>Click the &quot;Add&quot; button in the top-right corner</p></li><li><p>The content type menu appears with options:</p><ul><li><strong>Upload Documents</strong>: Add document files (PDF, Word, Excel, etc.)</li><li><strong>Create a Card</strong>: Build rich multimedia content cards</li><li><strong>Create Web Link</strong>: Add external web page references</li><li><strong>Add to Asset Library</strong>: Upload images and other assets for use in cards</li></ul></li><li><p>Click the desired option to navigate to the specific creation interface</p></li></ol><h3 id="viewing-and-editing-content" tabindex="-1">Viewing and Editing Content <a class="header-anchor" href="#viewing-and-editing-content" aria-label="Permalink to &quot;Viewing and Editing Content&quot;">​</a></h3><p>To view or edit an existing content item:</p><ol><li>Click anywhere on the content row in the table</li><li>The system navigates to the appropriate editor based on content type: <ul><li>Documents open in the document viewer</li><li>Cards open in the card designer</li><li>Links open in the link editor</li></ul></li></ol><h2 id="content-operations" tabindex="-1">Content Operations <a class="header-anchor" href="#content-operations" aria-label="Permalink to &quot;Content Operations&quot;">​</a></h2><h3 id="exporting-content-list" tabindex="-1">Exporting Content List <a class="header-anchor" href="#exporting-content-list" aria-label="Permalink to &quot;Exporting Content List&quot;">​</a></h3><p>To export the content list to Excel:</p><ol><li>Click the &quot;Export to Excel&quot; button (external link icon in top-right)</li><li>Confirm the export in the dialog that appears</li><li>The browser will download a CSV file</li><li>The export includes all currently visible content (respects active filters)</li></ol><h3 id="refreshing-content-data" tabindex="-1">Refreshing Content Data <a class="header-anchor" href="#refreshing-content-data" aria-label="Permalink to &quot;Refreshing Content Data&quot;">​</a></h3><p>To ensure you&#39;re viewing the most current data:</p><ol><li>Click the &quot;Refresh Data&quot; button (refresh icon in top-right)</li><li>The system will reload all content data from the server</li><li>This is useful after making changes or when multiple users are working simultaneously</li></ol><h2 id="understanding-content-types" tabindex="-1">Understanding Content Types <a class="header-anchor" href="#understanding-content-types" aria-label="Permalink to &quot;Understanding Content Types&quot;">​</a></h2><h3 id="documents" tabindex="-1">Documents <a class="header-anchor" href="#documents" aria-label="Permalink to &quot;Documents&quot;">​</a></h3><p>Documents can be various file types:</p><ul><li><strong>PDFs</strong>: Standard document format with fixed layout</li><li><strong>Office Documents</strong>: Word, Excel, PowerPoint files</li><li><strong>Text Files</strong>: Plain text, RTF, CSV, JSON, XML</li><li><strong>Media Files</strong>: MP4 videos, MP3 audio</li><li><strong>Code/Markup</strong>: HTML, Markdown</li></ul><p>Documents are processed by the AI and their content becomes searchable in knowledge bases.</p><h3 id="cards" tabindex="-1">Cards <a class="header-anchor" href="#cards" aria-label="Permalink to &quot;Cards&quot;">​</a></h3><p>Cards are rich content items created in the platform:</p><ul><li>Designed for engaging user interactions</li><li>Can contain text, images, buttons, and other interactive elements</li><li>Often used for frequently accessed information</li><li>Appear in the AI interface as structured responses</li></ul><h3 id="web-links" tabindex="-1">Web Links <a class="header-anchor" href="#web-links" aria-label="Permalink to &quot;Web Links&quot;">​</a></h3><p>Web links point to external resources:</p><ul><li>Reference websites outside the platform</li><li>Appear in search results and LaunchPad</li><li>Include title, description, and URL</li><li>Can be categorized with topics and tags</li></ul><h3 id="assets" tabindex="-1">Assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Assets&quot;">​</a></h3><p>Assets are supporting files:</p><ul><li>Images, icons, and graphics</li><li>Used within cards and other content</li><li>Stored in the asset library</li><li>Not directly processed by AI but support other content</li></ul><h3 id="other-content-types" tabindex="-1">Other Content Types <a class="header-anchor" href="#other-content-types" aria-label="Permalink to &quot;Other Content Types&quot;">​</a></h3><ul><li><strong>FAQ Items</strong>: Question and answer pairs</li><li><strong>Featured Content</strong>: Highlighted items for prominent display</li><li><strong>Web Crawler Content</strong>: Automatically gathered from websites</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective content management:</p><ol><li><p><strong>Naming Conventions</strong>:</p><ul><li>Use clear, descriptive names</li><li>Include content type in name when appropriate</li><li>Keep names concise but informative</li></ul></li><li><p><strong>Knowledge Base Organization</strong>:</p><ul><li>Assign content to appropriate knowledge bases</li><li>Consider creating specialized KBs for different departments or subjects</li><li>Review KB assignments periodically</li></ul></li><li><p><strong>Topics and Tags</strong>:</p><ul><li>Use topics for primary categorization</li><li>Use tags for more granular classification</li><li>Be consistent with tag naming</li><li>Don&#39;t over-tag content (5-7 tags maximum is ideal)</li></ul></li><li><p><strong>Regular Maintenance</strong>:</p><ul><li>Review older content for relevance</li><li>Update content when information changes</li><li>Remove duplicates or outdated material</li><li>Check for broken links</li></ul></li><li><p><strong>Search Optimization</strong>:</p><ul><li>Include relevant keywords in content names and descriptions</li><li>Use clear, specific topic categories</li><li>Add descriptive tags that users might search for</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Content list is empty</p><ul><li>Check if filters are active (blue filter button indicates active filters)</li><li>Click the &quot;Clear Filters&quot; button to remove all filters</li><li>Refresh the data using the refresh button</li><li>Verify you have permissions to view content</li></ul><p><strong>Issue</strong>: Cannot find specific content</p><ul><li>Try searching by partial name or description</li><li>Clear all filters and browse the complete list</li><li>Check if you&#39;re looking in the correct knowledge base</li><li>Verify the content exists and you have permissions to view it</li></ul><p><strong>Issue</strong>: Content appears in wrong format</p><ul><li>Check the file extension and content type</li><li>Some file types may be represented by generic icons</li><li>Verify the file was uploaded correctly</li></ul><p><strong>Issue</strong>: Knowledge base avatars not displaying correctly</p><ul><li>The KB store may need refreshing</li><li>Try refreshing the page</li><li>Check if the knowledge bases exist in the system</li></ul><p><strong>Issue</strong>: Filter shows no results</p><ul><li>Your filter combination may be too restrictive</li><li>Try removing one filter at a time to see what&#39;s causing the issue</li><li>Verify that content matching your criteria exists</li></ul><p><strong>Issue</strong>: Export not working</p><ul><li>Check browser download settings</li><li>Ensure you have proper permissions</li><li>Try with a smaller dataset by applying filters first</li></ul><hr><p>For additional assistance with content management, please contact your system administrator or refer to the platform documentation.</p>',88)]))}const p=t(a,[["render",l]]);export{u as __pageData,p as default};
